-- Legal check (23 November 2026): texts that said "no returns for a wrong size" or treated
-- "within 30 days" as a hard limit conflict with the 14-day right to cancel and the legal guarantee.
-- Sentence-level REPLACE: works with any line endings, and sentences already changed in the admin
-- aren't found, so they are left alone.

UPDATE "SiteSettings" SET "shippingReturnsText" = REPLACE(REPLACE(REPLACE("shippingReturnsText", 'Every item is printed on demand, just for you. Production usually takes 2–5 business days, after which your order ships with a tracking link. Delivery time depends on where you live; you''ll see the shipping options and costs at checkout.', 'Every item is printed on demand, just for you, and shipped worldwide. Production takes 2–5 business days for most items (longer for some specialty products), after which your order ships with a tracking link. You''ll see the shipping options, costs and delivery time at checkout.'), 'Because each item is made to order, we can''t take returns for a wrong size or a change of mind, so please check the size guide before ordering.', 'Changed your mind? You can cancel within 14 days after receiving your order, without giving a reason. See our refund policy for how it works.'), 'Did your order arrive damaged, misprinted or faulty? Contact us within 30 days of delivery with a photo, and we''ll send a free replacement or give you a refund.', 'Did your order arrive damaged, misprinted or faulty? Let us know as soon as possible, preferably within 30 days of delivery, with a photo, and we''ll send a free replacement or give you a refund.');

UPDATE "BlogPost" SET "content" = REPLACE(REPLACE(REPLACE("content", '2. **Your item is printed**, usually within 2 to 5 business days, by our production partner Printful.', '2. **Your item is printed** by our production partner Printful, usually within 2 to 5 business days. Specialty products such as knitwear take longer: see our [shipping policy](/shipping-policy).'), 'Delivery time after shipping depends on where you live.', 'We ship worldwide. Delivery time after shipping depends on where you live.'), 'If your item arrives damaged, misprinted or faulty, [contact us](/contact) within 30 days of delivery with a photo and we''ll make it right.', 'If your item arrives damaged, misprinted or faulty, [contact us](/contact) as soon as possible, preferably within 30 days of delivery, with a photo and we''ll make it right.'), "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'how-print-on-demand-works';

UPDATE "BlogPost" SET "content" = REPLACE("content", 'Because every item is made to order, we can''t take returns for a wrong size. A minute with a measuring tape saves a lot of disappointment, so here''s how to get it right.', 'Ordered the wrong size? You can cancel within 14 days (see our [refund policy](/refund-policy)), but sending it back costs you time and postage. A minute with a measuring tape saves a lot of hassle, so here''s how to get it right.'), "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'how-to-find-your-size';

UPDATE "BlogPost" SET "content" = REPLACE(REPLACE(REPLACE("content", 'Every item is printed on demand. Production usually takes **2 to 5 business days**, then your order ships with a **tracking link** by email.', 'Every item is printed on demand and **we ship worldwide**. Production usually takes **2 to 5 business days** for most items (specialty products such as knitwear take longer), then your order ships with a **tracking link** by email.'), 'Because each item is made to order, we **can''t take returns for a wrong size or a change of mind**. Please check the [size guide](/blog/how-to-find-your-size) before ordering.', 'Changed your mind or ordered the wrong size? You can **cancel within 14 days** after receiving your order, without giving a reason. Read how it works in our [refund policy](/refund-policy). To avoid the hassle, check the [size guide](/blog/how-to-find-your-size) before ordering.'), '[Contact us](/contact) within 30 days of delivery with a photo, and we''ll send a free replacement or give you a refund.', '[Contact us](/contact) as soon as possible, preferably within 30 days of delivery, with a photo, and we''ll send a free replacement or give you a refund.'), "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'shipping-returns-and-payment';
